/**
 * An inline brand logo for a catalog preset, or null when there's no mark for it
 * (the caller falls back to a codicon). Parsed via DOMParser so the path data is
 * correctly SVG-namespaced; the markup is a trusted build-time constant.
 */
/** Local-CLI presets reuse the underlying vendor's mark. */
const ALIASES: Record<string, string> = {
  "claude-code": "anthropic",
  codex: "openai",
  "gemini-cli": "google",
};

export function providerLogo(presetId: string, size = 18): SVGElement | null {
  const inner = LOGO_PATHS[ALIASES[presetId] ?? presetId];
  if (!inner) {
    return null;
  }
  const doc = new DOMParser().parseFromString(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor">${inner}</svg>`,
    "image/svg+xml",
  );
  const svg = doc.documentElement as unknown as SVGElement;
  svg.setAttribute("width", String(size));
  svg.setAttribute("height", String(size));
  svg.setAttribute("aria-hidden", "true");
  svg.classList.add("ai-logo");
  return document.importNode(svg, true) as SVGElement;
}

/** Whether we have a real brand mark for this preset. */
export function hasProviderLogo(presetId: string): boolean {
  return presetId in LOGO_PATHS;
}
